using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
        // Preserve the old property name so existing documents are still found.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id values no longer include the discriminator prefix.
        // EF 8 generated ids like "Blog|1"; EF 9 uses just the key value.
        // Use IdProperty() to keep reading existing "id" values that contain the old format,
        // and HasPartitionKey to align with the default id-based partition key.
        modelBuilder.Entity<Blog>().ToContainer("Blogs");

        // Breaking change 3: HasIndex() is no longer silently ignored for Cosmos — it now throws.
        // Removed the unsupported HasIndex call above.
        // (Cosmos DB manages indexing at the container level, not via EF.)
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

